// Package baseline defines the security baseline model and the catalog of
// baselines embedded in the plugin.
//
// The baseline data is generated by cmd/sctimport from Microsoft's Security
// Compliance Toolkit and must not be edited by hand.
package baseline

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// Kind identifies how a setting is stored on the guest and which payload field
// of a Setting is set.
type Kind string

const (
	KindRegistry      Kind = "registry"
	KindUserRight     Kind = "user_right"
	KindAccountPolicy Kind = "account_policy"
	KindAuditPolicy   Kind = "audit_policy"
	KindService       Kind = "service"
)

// Profile selects the variant of a baseline that matches the machine's domain
// membership.
type Profile string

const (
	ProfileDomainJoined    Profile = "domain_joined"
	ProfileNonDomainJoined Profile = "non_domain_joined"
)

// Setting is one configuration item of a baseline. Exactly one payload field
// matching Kind is set, and ID is derived from that payload.
type Setting struct {
	ID            string         `json:"id"`
	Kind          Kind           `json:"kind"`
	Description   string         `json:"description"`
	Component     string         `json:"component"`
	Registry      *RegistryValue `json:"registry,omitempty"`
	UserRight     *UserRight     `json:"user_right,omitempty"`
	AccountPolicy *AccountPolicy `json:"account_policy,omitempty"`
	AuditPolicy   *AuditPolicy   `json:"audit_policy,omitempty"`
	Service       *Service       `json:"service,omitempty"`
}

// RegistryValue is a value below HKLM. Type is RegDWORD, RegSZ or RegAbsent,
// and Data holds the decimal DWORD or the string.
type RegistryValue struct {
	Path string `json:"path"`
	Name string `json:"name"`
	Type string `json:"type"`
	Data string `json:"data"`
}

const (
	RegDWORD  = "REG_DWORD"
	RegSZ     = "REG_SZ"
	RegAbsent = "ABSENT"
)

// UserRight assigns a privilege or logon right to exactly the listed SIDs. An
// empty list means the right is assigned to no one.
type UserRight struct {
	Right string   `json:"right"`
	SIDs  []string `json:"sids"`
}

// AccountPolicy is a [System Access] entry of the local security policy.
type AccountPolicy struct {
	Name  string `json:"name"`
	Value string `json:"value"`
}

// AuditPolicy sets an advanced audit subcategory. Setting is 0 for no
// auditing, 1 for success, 2 for failure and 3 for both.
type AuditPolicy struct {
	SubcategoryGUID string `json:"subcategory_guid"`
	Subcategory     string `json:"subcategory"`
	Setting         int    `json:"setting"`
}

// Service sets a service start type: 2 automatic, 3 manual or 4 disabled.
type Service struct {
	Name      string `json:"name"`
	StartType int    `json:"start_type"`
}

// Source records the Microsoft download a baseline was generated from.
type Source struct {
	Package     string `json:"package"`
	URL         string `json:"url"`
	SHA256      string `json:"sha256"`
	PolicyRules string `json:"policy_rules"`
}

// Applicability lists the product type and builds a baseline applies to.
type Applicability struct {
	ProductType string `json:"product_type"`
	Builds      []int  `json:"builds"`
}

// Exclusion records a part of the Microsoft package that is not implemented,
// and why.
type Exclusion struct {
	Item   string `json:"item"`
	Reason string `json:"reason"`
}

// Baseline is a complete Microsoft security baseline for one Windows release.
type Baseline struct {
	ID                       string        `json:"id"`
	Name                     string        `json:"name"`
	Version                  string        `json:"version"`
	Source                   Source        `json:"source"`
	AppliesTo                Applicability `json:"applies_to"`
	Components               []string      `json:"components"`
	Excluded                 []Exclusion   `json:"excluded"`
	Settings                 []Setting     `json:"settings"`
	NonDomainJoinedOverrides []Setting     `json:"non_domain_joined_overrides"`
}

// SettingsFor returns a copy of the baseline's settings for profile p. For the
// non-domain-joined profile, settings with a non-domain-joined override are
// replaced by that override.
//
// Author: Lars Krogh
// Version: 1.0.0
func (b *Baseline) SettingsFor(p Profile) []Setting {
	out := make([]Setting, len(b.Settings))
	copy(out, b.Settings)
	if p != ProfileNonDomainJoined {
		return out
	}
	overrides := make(map[string]Setting, len(b.NonDomainJoinedOverrides))
	for _, o := range b.NonDomainJoinedOverrides {
		overrides[strings.ToLower(o.ID)] = o
	}
	for i, s := range out {
		if o, ok := overrides[strings.ToLower(s.ID)]; ok {
			out[i] = o
		}
	}
	return out
}

// Validate checks the baseline's metadata, every setting and every override.
// Setting IDs must be unique, and each override must replace an existing
// setting exactly once.
//
// Returns:
//   - error: The first problem found, or nil.
//
// Author: Lars Krogh
// Version: 1.0.0
func (b *Baseline) Validate() error {
	if b.ID == "" || b.Name == "" || b.Version == "" {
		return errors.New("baseline is missing id, name or version")
	}
	if b.Source.URL == "" || b.Source.SHA256 == "" {
		return fmt.Errorf("baseline %s: source url and sha256 are required", b.ID)
	}
	if b.AppliesTo.ProductType != "server" && b.AppliesTo.ProductType != "workstation" {
		return fmt.Errorf("baseline %s: invalid product type %q", b.ID, b.AppliesTo.ProductType)
	}
	if len(b.AppliesTo.Builds) == 0 {
		return fmt.Errorf("baseline %s: no applicable builds", b.ID)
	}
	seen := make(map[string]bool, len(b.Settings))
	for _, s := range b.Settings {
		key := strings.ToLower(s.ID)
		if seen[key] {
			return fmt.Errorf("baseline %s: duplicate setting %s", b.ID, s.ID)
		}
		seen[key] = true
		if err := s.Validate(); err != nil {
			return fmt.Errorf("baseline %s: %w", b.ID, err)
		}
	}
	overridden := make(map[string]bool, len(b.NonDomainJoinedOverrides))
	for _, s := range b.NonDomainJoinedOverrides {
		if err := s.Validate(); err != nil {
			return fmt.Errorf("baseline %s override: %w", b.ID, err)
		}
		key := strings.ToLower(s.ID)
		if !seen[key] {
			return fmt.Errorf("baseline %s: override %s does not replace a baseline setting", b.ID, s.ID)
		}
		if overridden[key] {
			return fmt.Errorf("baseline %s: duplicate override %s", b.ID, s.ID)
		}
		overridden[key] = true
	}
	return nil
}

// Validate checks that the setting has a description and a component, exactly
// one payload matching its kind, valid payload data, and the ID derived from
// that payload.
//
// Returns:
//   - error: The first problem found, or nil.
//
// Author: Lars Krogh
// Version: 1.0.0
func (s *Setting) Validate() error {
	if s.Description == "" || s.Component == "" {
		return fmt.Errorf("setting %s: description and component are required", s.ID)
	}
	payloads := 0
	for _, present := range []bool{s.Registry != nil, s.UserRight != nil, s.AccountPolicy != nil, s.AuditPolicy != nil, s.Service != nil} {
		if present {
			payloads++
		}
	}
	if payloads != 1 {
		return fmt.Errorf("setting %s: expected exactly one payload, found %d", s.ID, payloads)
	}
	var want string
	switch s.Kind {
	case KindRegistry:
		if s.Registry == nil {
			return fmt.Errorf("setting %s: missing registry payload", s.ID)
		}
		switch s.Registry.Type {
		case RegDWORD:
			if _, err := strconv.ParseUint(s.Registry.Data, 10, 32); err != nil {
				return fmt.Errorf("setting %s: REG_DWORD data %q is not a decimal uint32", s.ID, s.Registry.Data)
			}
		case RegSZ, RegAbsent:
		default:
			return fmt.Errorf("setting %s: unsupported registry type %s", s.ID, s.Registry.Type)
		}
		want = RegistryID(s.Registry.Path, s.Registry.Name)
	case KindUserRight:
		if s.UserRight == nil {
			return fmt.Errorf("setting %s: missing user_right payload", s.ID)
		}
		want = UserRightID(s.UserRight.Right)
	case KindAccountPolicy:
		if s.AccountPolicy == nil {
			return fmt.Errorf("setting %s: missing account_policy payload", s.ID)
		}
		want = AccountPolicyID(s.AccountPolicy.Name)
	case KindAuditPolicy:
		if s.AuditPolicy == nil {
			return fmt.Errorf("setting %s: missing audit_policy payload", s.ID)
		}
		if s.AuditPolicy.Setting < 0 || s.AuditPolicy.Setting > 3 {
			return fmt.Errorf("setting %s: invalid audit setting %d", s.ID, s.AuditPolicy.Setting)
		}
		want = AuditPolicyID(s.AuditPolicy.SubcategoryGUID)
	case KindService:
		if s.Service == nil {
			return fmt.Errorf("setting %s: missing service payload", s.ID)
		}
		if s.Service.StartType < 2 || s.Service.StartType > 4 {
			return fmt.Errorf("setting %s: invalid service start type %d", s.ID, s.Service.StartType)
		}
		want = ServiceID(s.Service.Name)
	default:
		return fmt.Errorf("setting %s: unknown kind %q", s.ID, s.Kind)
	}
	if s.ID != want {
		return fmt.Errorf("setting %s: id does not match payload (want %s)", s.ID, want)
	}
	return nil
}

// ExpectedValue describes the value the baseline requires, in the form used in
// reports. It returns an empty string for an unknown kind.
//
// Author: Lars Krogh
// Version: 1.0.0
func (s *Setting) ExpectedValue() string {
	switch s.Kind {
	case KindRegistry:
		if s.Registry.Type == RegAbsent {
			return "(value absent)"
		}
		return fmt.Sprintf("%s %s", s.Registry.Type, s.Registry.Data)
	case KindUserRight:
		if len(s.UserRight.SIDs) == 0 {
			return "(no one)"
		}
		return strings.Join(s.UserRight.SIDs, ",")
	case KindAccountPolicy:
		return s.AccountPolicy.Value
	case KindAuditPolicy:
		return auditSettingName(s.AuditPolicy.Setting)
	case KindService:
		return serviceStartTypeName(s.Service.StartType)
	}
	return ""
}

// RegistryID returns the setting ID of the HKLM value name below path.
//
// Author: Lars Krogh
// Version: 1.0.0
func RegistryID(path, name string) string { return "registry:HKLM\\" + path + "\\" + name }

// UserRightID returns the setting ID of a user right.
//
// Author: Lars Krogh
// Version: 1.0.0
func UserRightID(right string) string { return "user_right:" + right }

// AccountPolicyID returns the setting ID of a [System Access] entry.
//
// Author: Lars Krogh
// Version: 1.0.0
func AccountPolicyID(name string) string { return "account_policy:" + name }

// AuditPolicyID returns the setting ID of an audit subcategory. The GUID is
// lower-cased so that IDs match regardless of how the source wrote it.
//
// Author: Lars Krogh
// Version: 1.0.0
func AuditPolicyID(guid string) string { return "audit_policy:" + strings.ToLower(guid) }

// ServiceID returns the setting ID of a service start type.
//
// Author: Lars Krogh
// Version: 1.0.0
func ServiceID(name string) string { return "service:" + name }

// auditSettingName returns the Group Policy name of an audit setting value.
//
// Author: Lars Krogh
// Version: 1.0.0
func auditSettingName(v int) string {
	switch v {
	case 0:
		return "No Auditing"
	case 1:
		return "Success"
	case 2:
		return "Failure"
	case 3:
		return "Success and Failure"
	}
	return fmt.Sprintf("invalid(%d)", v)
}

// serviceStartTypeName returns the name of a service start type value.
//
// Author: Lars Krogh
// Version: 1.0.0
func serviceStartTypeName(v int) string {
	switch v {
	case 2:
		return "Automatic"
	case 3:
		return "Manual"
	case 4:
		return "Disabled"
	}
	return fmt.Sprintf("invalid(%d)", v)
}
